mapper.select:
select collect.*, business.name as business_name, goods.img as goods_img, goods.name as goods_name,
       goods.price as goods_price, goods.unit as goods_unit
from collect
left join business on collect.business_id = business.id
left join goods on collect.goods_id = goods.id

    and collect.id = #{id}
    and collect.user_id = #{userId}
    and collect.business_id = #{businessId}
    and collect.goods_id = #{goodsId}

order by collect.id desc
